  let origAbortController;

  beforeAll(() => {
    // Mock AbortController environment
    class MockAbortSignal {
      constructor() {
        this.aborted = false;
        this._handlers = [];
      }
      addEventListener(type, handler) {
        if (type === 'abort') this._handlers.push(handler);
      }
      removeEventListener(type, handler) {
        if (type === 'abort') {
          this._handlers = this._handlers.filter(h => h !== handler);
        }
      }
      dispatchAbort() {
        this.aborted = true;
        for (const h of this._handlers) {
          try {
            h();
          } catch (e) {
            // ignore
          }
        }
      }
    }

    class MockAbortController {
      constructor() {
        this.signal = new MockAbortSignal();
        this._aborted = false;
      }
      abort() {
        if (!this._aborted) {
          this._aborted = true;
          this.signal.dispatchAbort();
        }
      }
    }

    origAbortController = global.AbortController;
    global.AbortController = MockAbortController;
